package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

// Exact six Salesforce-admitted async lifecycle contracts; original mixed component APIs and project retained.
func TestRunAsyncLifecycleAdmittedContracts(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeAsyncJobsProbe25.cls"), "@IsTest private class GladeAsyncJobsProbe25 {\nprivate static void snapshot(List<Object> rows,String phase,Id mainId){\n List<AsyncApexJob> raw=[SELECT ApexClass.Name,JobType,Status,ParentJobId,JobItemsProcessed,TotalJobItems,NumberOfErrors FROM AsyncApexJob];\n List<String> jobs=new List<String>();for(AsyncApexJob job:raw){jobs.add(JSON.serialize(new List<Object>{job.ApexClass.Name,job.JobType,job.Status,job.Id==mainId,job.ParentJobId!=null,mainId!=null&&job.ParentJobId==mainId,job.JobItemsProcessed,job.TotalJobItems,job.NumberOfErrors}));}jobs.sort();\n List<String> crons=GladeAsyncCron31.snapshot();\n List<String> effects=new List<String>();for(Account a:[SELECT Name,Description FROM Account WHERE Name LIKE 'owned-%'])effects.add(JSON.serialize(new List<Object>{a.Name,a.Description}));effects.sort();\n rows.add(new Map<String,Object>{'phase'=>phase,'count'=>raw.size(),'jobs'=>jobs,'cron'=>crons,'effects'=>effects});}\nprivate static void run(String mode,String prior,Boolean withInput){List<Object> rows=new List<Object>();if(withInput)insert new Account(Name='owned-async-input');if(prior=='queue')GladeAsyncQueue29.enqueue();if(prior=='schedule')GladeAsyncImproved48.scheduleJob();snapshot(rows,'beforeStart',null);Test.startTest();Id mainId=Database.executeBatch(new GladeAsyncMain25(mode));snapshot(rows,'afterEnqueue',mainId);try{Test.stopTest();rows.add(new Map<String,Object>{'phase'=>'stop','returned'=>true});}catch(Exception e){rows.add(new Map<String,Object>{'phase'=>'stop','type'=>e.getTypeName(),'message'=>e.getMessage()});}snapshot(rows,'afterStop',mainId);System.assertEquals(4,rows.size(),'All phases retained');String payload=JSON.serialize(rows);System.assert(payload.length()<2900,'Owned async observation exceeds bound');verify(rows,mode,prior,withInput);}\n@IsTest static void oneRecordBatchOnly(){run('none','none',true);}\n@IsTest static void emptyBatchOnly(){run('none','none',false);}\n@IsTest static void finishQueuesWithoutPrior(){run('queue','none',true);}\n@IsTest static void finishQueuesWithPrior(){run('queue','queue',true);}\n@IsTest static void finishSchedulesWithoutPrior(){run('schedule','none',true);}\n@IsTest static void finishSchedulesWithPrior(){run('schedule','schedule',true);}\n\nprivate static void verify(List<Object> rows,String mode,String prior,Boolean withInput){\nString encoded;\nif(mode=='none'&&prior=='none'&&withInput){encoded='[{\"effects\":[\"[\\\\\"owned-async-input\\\\\",null]\"],\"cron\":[],\"jobs\":[],\"count\":0,\"phase\":\"beforeStart\"},{\"effects\":[\"[\\\\\"owned-async-input\\\\\",null]\"],\"cron\":[],\"jobs\":[\"[\\\\\"GladeAsyncMain25\\\\\",\\\\\"BatchApex\\\\\",\\\\\"Queued\\\\\",true,false,false,0,0,0]\"],\"count\":1,\"phase\":\"afterEnqueue\"},{\"returned\":true,\"phase\":\"stop\"},{\"effects\":[\"[\\\\\"owned-async-finished\\\\\",\\\\\"none\\\\\"]\",\"[\\\\\"owned-async-input\\\\\",\\\\\"executed\\\\\"]\"],\"cron\":[],\"jobs\":[\"[\\\\\"GladeAsyncMain25\\\\\",\\\\\"BatchApex\\\\\",\\\\\"Completed\\\\\",true,false,false,1,1,0]\",\"[\\\\\"GladeAsyncMain25\\\\\",\\\\\"BatchApexWorker\\\\\",\\\\\"Completed\\\\\",false,true,true,1,1,0]\"],\"count\":2,\"phase\":\"afterStop\"}]';}\nelse if(mode=='none'&&prior=='none'&&!withInput){encoded='[{\"effects\":[],\"cron\":[],\"jobs\":[],\"count\":0,\"phase\":\"beforeStart\"},{\"effects\":[],\"cron\":[],\"jobs\":[\"[\\\\\"GladeAsyncMain25\\\\\",\\\\\"BatchApex\\\\\",\\\\\"Queued\\\\\",true,false,false,0,0,0]\"],\"count\":1,\"phase\":\"afterEnqueue\"},{\"returned\":true,\"phase\":\"stop\"},{\"effects\":[\"[\\\\\"owned-async-finished\\\\\",\\\\\"none\\\\\"]\"],\"cron\":[],\"jobs\":[\"[\\\\\"GladeAsyncMain25\\\\\",\\\\\"BatchApex\\\\\",\\\\\"Completed\\\\\",true,false,false,0,0,0]\"],\"count\":1,\"phase\":\"afterStop\"}]';}\nelse if(mode=='queue'&&prior=='none'&&withInput){encoded='[{\"effects\":[\"[\\\\\"owned-async-input\\\\\",null]\"],\"cron\":[],\"jobs\":[],\"count\":0,\"phase\":\"beforeStart\"},{\"effects\":[\"[\\\\\"owned-async-input\\\\\",null]\"],\"cron\":[],\"jobs\":[\"[\\\\\"GladeAsyncMain25\\\\\",\\\\\"BatchApex\\\\\",\\\\\"Queued\\\\\",true,false,false,0,0,0]\"],\"count\":1,\"phase\":\"afterEnqueue\"},{\"returned\":true,\"phase\":\"stop\"},{\"effects\":[\"[\\\\\"owned-async-finished\\\\\",\\\\\"queue\\\\\"]\",\"[\\\\\"owned-async-input\\\\\",\\\\\"executed\\\\\"]\"],\"cron\":[\"[\\\\\"GladeAsyncLegacy29\\\\\",\\\\\"WAITING\\\\\"]\"],\"jobs\":[\"[\\\\\"GladeAsyncLegacy29\\\\\",\\\\\"BatchApex\\\\\",\\\\\"Queued\\\\\",false,false,false,0,0,0]\",\"[\\\\\"GladeAsyncMain25\\\\\",\\\\\"BatchApex\\\\\",\\\\\"Completed\\\\\",true,false,false,1,1,0]\",\"[\\\\\"GladeAsyncMain25\\\\\",\\\\\"BatchApexWorker\\\\\",\\\\\"Completed\\\\\",false,true,true,1,1,0]\",\"[\\\\\"GladeAsyncQueue29\\\\\",\\\\\"Queueable\\\\\",\\\\\"Completed\\\\\",false,false,false,0,0,0]\"],\"count\":4,\"phase\":\"afterStop\"}]';}\nelse if(mode=='queue'&&prior=='queue'&&withInput){encoded='[{\"effects\":[\"[\\\\\"owned-async-input\\\\\",null]\"],\"cron\":[],\"jobs\":[\"[\\\\\"GladeAsyncQueue29\\\\\",\\\\\"Queueable\\\\\",\\\\\"Queued\\\\\",false,false,false,0,0,0]\"],\"count\":1,\"phase\":\"beforeStart\"},{\"effects\":[\"[\\\\\"owned-async-input\\\\\",null]\"],\"cron\":[],\"jobs\":[\"[\\\\\"GladeAsyncMain25\\\\\",\\\\\"BatchApex\\\\\",\\\\\"Queued\\\\\",true,false,false,0,0,0]\",\"[\\\\\"GladeAsyncQueue29\\\\\",\\\\\"Queueable\\\\\",\\\\\"Queued\\\\\",false,false,false,0,0,0]\"],\"count\":2,\"phase\":\"afterEnqueue\"},{\"returned\":true,\"phase\":\"stop\"},{\"effects\":[\"[\\\\\"owned-async-finished\\\\\",\\\\\"queue\\\\\"]\",\"[\\\\\"owned-async-input\\\\\",\\\\\"executed\\\\\"]\",\"[\\\\\"owned-schedule-error\\\\\",\\\\\"System.AsyncException:The Apex job named \\\\\\\\\\\\\"GladeAsyncLegacy29\\\\\\\\\\\\\" is already scheduled for execution.\\\\\"]\"],\"cron\":[\"[\\\\\"GladeAsyncLegacy29\\\\\",\\\\\"WAITING\\\\\"]\"],\"jobs\":[\"[\\\\\"GladeAsyncLegacy29\\\\\",\\\\\"BatchApex\\\\\",\\\\\"Queued\\\\\",false,false,false,0,0,0]\",\"[\\\\\"GladeAsyncMain25\\\\\",\\\\\"BatchApex\\\\\",\\\\\"Completed\\\\\",true,false,false,1,1,0]\",\"[\\\\\"GladeAsyncMain25\\\\\",\\\\\"BatchApexWorker\\\\\",\\\\\"Completed\\\\\",false,true,true,1,1,0]\",\"[\\\\\"GladeAsyncQueue29\\\\\",\\\\\"Queueable\\\\\",\\\\\"Completed\\\\\",false,false,false,0,0,0]\",\"[\\\\\"GladeAsyncQueue29\\\\\",\\\\\"Queueable\\\\\",\\\\\"Completed\\\\\",false,false,false,0,0,0]\"],\"count\":5,\"phase\":\"afterStop\"}]';}\nelse if(mode=='schedule'&&prior=='none'&&withInput){encoded='[{\"effects\":[\"[\\\\\"owned-async-input\\\\\",null]\"],\"cron\":[],\"jobs\":[],\"count\":0,\"phase\":\"beforeStart\"},{\"effects\":[\"[\\\\\"owned-async-input\\\\\",null]\"],\"cron\":[],\"jobs\":[\"[\\\\\"GladeAsyncMain25\\\\\",\\\\\"BatchApex\\\\\",\\\\\"Queued\\\\\",true,false,false,0,0,0]\"],\"count\":1,\"phase\":\"afterEnqueue\"},{\"returned\":true,\"phase\":\"stop\"},{\"effects\":[\"[\\\\\"owned-async-finished\\\\\",\\\\\"schedule\\\\\"]\",\"[\\\\\"owned-async-input\\\\\",\\\\\"executed\\\\\"]\",\"[\\\\\"owned-schedule-error\\\\\",\\\\\"System.AsyncException:System.scheduleBatch cannot be called from a batch start, batch execute, or future method.\\\\\"]\"],\"cron\":[],\"jobs\":[\"[\\\\\"GladeAsyncMain25\\\\\",\\\\\"BatchApex\\\\\",\\\\\"Completed\\\\\",true,false,false,1,1,0]\",\"[\\\\\"GladeAsyncMain25\\\\\",\\\\\"BatchApexWorker\\\\\",\\\\\"Completed\\\\\",false,true,true,1,1,0]\"],\"count\":2,\"phase\":\"afterStop\"}]';}\nelse if(mode=='schedule'&&prior=='schedule'&&withInput){encoded='[{\"effects\":[\"[\\\\\"owned-async-input\\\\\",null]\"],\"cron\":[\"[\\\\\"GladeAsyncImproved48\\\\\",\\\\\"WAITING\\\\\"]\"],\"jobs\":[],\"count\":0,\"phase\":\"beforeStart\"},{\"effects\":[\"[\\\\\"owned-async-input\\\\\",null]\"],\"cron\":[\"[\\\\\"GladeAsyncImproved48\\\\\",\\\\\"WAITING\\\\\"]\"],\"jobs\":[\"[\\\\\"GladeAsyncMain25\\\\\",\\\\\"BatchApex\\\\\",\\\\\"Queued\\\\\",true,false,false,0,0,0]\"],\"count\":1,\"phase\":\"afterEnqueue\"},{\"returned\":true,\"phase\":\"stop\"},{\"effects\":[\"[\\\\\"owned-async-finished\\\\\",\\\\\"schedule\\\\\"]\",\"[\\\\\"owned-async-input\\\\\",\\\\\"executed\\\\\"]\",\"[\\\\\"owned-schedule-error\\\\\",\\\\\"System.AsyncException:System.scheduleBatch cannot be called from a batch start, batch execute, or future method.\\\\\"]\"],\"cron\":[\"[\\\\\"GladeAsyncImproved48\\\\\",\\\\\"WAITING\\\\\"]\"],\"jobs\":[\"[\\\\\"GladeAsyncImproved48\\\\\",\\\\\"BatchApex\\\\\",\\\\\"Queued\\\\\",false,false,false,0,0,0]\",\"[\\\\\"GladeAsyncMain25\\\\\",\\\\\"BatchApex\\\\\",\\\\\"Completed\\\\\",true,false,false,1,1,0]\",\"[\\\\\"GladeAsyncMain25\\\\\",\\\\\"BatchApexWorker\\\\\",\\\\\"Completed\\\\\",false,true,true,1,1,0]\"],\"count\":3,\"phase\":\"afterStop\"}]';}\nelse{System.assert(false,'Unexpected owned async input');return;}\nList<Object> expected=(List<Object>)JSON.deserializeUntyped(encoded);\nSystem.assertEquals(expected.size(),rows.size(),'Exact phase population');\nfor(Integer i=0;i<expected.size();i++){\n Map<String,Object> want=(Map<String,Object>)expected[i];Map<String,Object> got=(Map<String,Object>)rows[i];\n System.assertEquals(want.keySet(),got.keySet(),'Exact phase fields '+i);\n for(String key:want.keySet()){\n  if(key=='jobs'||key=='cron'||key=='effects'){\n   List<Object> values=(List<Object>)want.get(key);List<String> actual=(List<String>)got.get(key);\n   System.assertEquals(values.size(),actual.size(),'Exact list population '+i+':'+key);\n   for(Integer j=0;j<values.size();j++)System.assertEquals(values[j],actual[j],'Exact list value '+i+':'+key+':'+j);\n  }else System.assertEquals(want.get(key),got.get(key),'Exact phase value '+i+':'+key);\n }\n}\n}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeAsyncJobsProbe25.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>25.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeAsyncMain25.cls"), "global class GladeAsyncMain25 implements Database.Batchable<SObject> {\n private String mode; global GladeAsyncMain25(String requested){mode=requested;}\n global Database.QueryLocator start(Database.BatchableContext context){return Database.getQueryLocator([SELECT Id,Description FROM Account WHERE Name='owned-async-input']);}\n global void execute(Database.BatchableContext context,List<SObject> records){for(SObject row:records)row.put('Description','executed');update records;}\n global void finish(Database.BatchableContext context){if(mode=='queue')GladeAsyncQueue29.enqueue();if(mode=='schedule')GladeAsyncImproved48.scheduleJob();insert new Account(Name='owned-async-finished',Description=mode);}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeAsyncMain25.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>25.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeAsyncQueue29.cls"), "public class GladeAsyncQueue29 implements Queueable {\n public static void enqueue(){System.enqueueJob(new GladeAsyncQueue29());}\n public void execute(QueueableContext context){GladeAsyncLegacy29.scheduleJob();}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeAsyncQueue29.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>29.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeAsyncLegacy29.cls"), "global class GladeAsyncLegacy29 implements Database.Batchable<SObject> {\n global Database.QueryLocator start(Database.BatchableContext context){return Database.getQueryLocator([SELECT Id FROM Account WHERE Name='owned-no-target']);}\n global void execute(Database.BatchableContext context,List<SObject> records){insert new Account(Name='owned-nested-executed',Description='legacy');}\n global void finish(Database.BatchableContext context){insert new Account(Name='owned-nested-finished',Description='legacy');}\n public static void scheduleJob(){try{System.scheduleBatch(new GladeAsyncLegacy29(),'GladeAsyncLegacy29',5,2000);}catch(AsyncException e){insert new Account(Name='owned-schedule-error',Description=e.getTypeName()+':'+e.getMessage());}}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeAsyncLegacy29.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>29.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeAsyncImproved48.cls"), "public class GladeAsyncImproved48 implements Database.Batchable<SObject> {\n public Database.QueryLocator start(Database.BatchableContext context){return Database.getQueryLocator([SELECT Id FROM Account WHERE Name='owned-no-target']);}\n public void execute(Database.BatchableContext context,List<SObject> records){insert new Account(Name='owned-nested-executed',Description='improved');}\n public void finish(Database.BatchableContext context){insert new Account(Name='owned-nested-finished',Description='improved');}\n public static void scheduleJob(){try{System.scheduleBatch(new GladeAsyncImproved48(),'GladeAsyncImproved48',1,100);}catch(AsyncException e){insert new Account(Name='owned-schedule-error',Description=e.getTypeName()+':'+e.getMessage());}}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeAsyncImproved48.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>48.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeAsyncCron31.cls"), "public class GladeAsyncCron31 {\n public static List<String> snapshot(){\n List<String> crons=new List<String>();for(CronTrigger cron:[SELECT CronJobDetail.Name,State FROM CronTrigger])crons.add(JSON.serialize(new List<Object>{cron.CronJobDetail.Name,cron.State}));crons.sort();\n return crons;\n }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeAsyncCron31.cls-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\">\n    <apiVersion>31.0</apiVersion>\n    <status>Active</status>\n</ApexClass>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}], \"sourceApiVersion\": \"61.0\"}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 6 || got.Passed != 6 || got.Failed != 0 || got.Errors != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("Async lifecycle contracts failed: %s", data)
	}
}
